\set ON_ERROR_STOP on
BEGIN;
DO $vedu_dsa_18$
DECLARE
 v_course bigint;
 v_total int;
 rec record;
 item jsonb;
 question jsonb;
 answer text;
 v_quiz bigint;
 v_qid bigint;
 v_order int;
 v_answer_order int;
 v_bad int;
BEGIN
 SELECT course_id INTO v_course FROM lms.curated_courses WHERE course_key='dsa';
 IF v_course IS NULL THEN RAISE EXCEPTION 'DSA course_key=dsa does not exist'; END IF;
 SELECT count(*) INTO v_total FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
 WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted;
 IF v_total<>10 THEN RAISE EXCEPTION 'Expected 10 published DSA lessons; got %',v_total; END IF;
 -- Preflight all lesson titles and quiz ownership before making any changes.
 FOR rec IN SELECT l.lesson_id,l.title,l.content,row_number() OVER(ORDER BY l.lesson_order,l.lesson_id) rn
 FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
 WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted
 LOOP
  item := ($data$[{"order":1,"title":"Tổng quan cấu trúc dữ liệu và giải thuật","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 01 — Tổng quan cấu trúc dữ liệu và giải thuật\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — So sánh cấu trúc dữ liệu\nViết chương trình lưu 5 sinh viên (mã, tên, điểm) vào danh sách, cho phép tìm theo mã và thống kê điểm trung bình. Vẽ sơ đồ mô tả đầu vào, xử lý, đầu ra.\n\nCA KIỂM THỬ BẮT BUỘC\nDanh sách rỗng; một sinh viên; mã trùng; tìm mã không tồn tại; điểm 0 và 10.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Cấu trúc dữ liệu dùng để làm gì?","options":["Tổ chức và lưu dữ liệu để thao tác hiệu quả","Chỉ tạo giao diện đồ họa","Thay thế hệ điều hành","Chỉ lưu tập tin âm thanh"]},{"text":"Giải thuật là gì?","options":["Dãy bước hữu hạn để giải một bài toán","Một ngôn ngữ lập trình cụ thể","Tên của bộ xử lý","Một kiểu tệp dữ liệu"]},{"text":"Đặc trưng nào thường cần đánh giá khi chọn giải thuật?","options":["Thời gian và bộ nhớ sử dụng","Màu sắc màn hình","Tên tác giả duy nhất","Dung lượng ảnh nền"]},{"text":"Dữ liệu đầu vào của thuật toán tìm lớn nhất là gì?","options":["Một tập giá trị cần so sánh","Mã lệnh giao diện","Tên hệ điều hành","Tệp CSS"]},{"text":"Tính đúng đắn của giải thuật nghĩa là gì?","options":["Cho kết quả đúng theo đặc tả với đầu vào hợp lệ","Luôn chạy nhanh nhất","Không dùng bộ nhớ","Có nhiều dòng code"]},{"text":"Cấu trúc nào hỗ trợ truy cập phần tử qua chỉ số?","options":["Mảng","Danh sách liên kết đơn chỉ có con trỏ đầu","Ngăn xếp chỉ cho pop","Hàng đợi chỉ cho dequeue"]},{"text":"Giải thuật cần điều kiện dừng để làm gì?","options":["Tránh thực hiện vô hạn với đầu vào hợp lệ","Tăng số vòng lặp","Tạo màu cho kết quả","Buộc sử dụng đệ quy"]},{"text":"Tính trừu tượng dữ liệu (ADT) mô tả điều gì?","options":["Các phép toán và hành vi mà không buộc cách cài đặt","Một tệp PDF","Địa chỉ IP của máy","Tốc độ CPU cố định"]},{"text":"Một phép kiểm thử biên cho tập dữ liệu là gì?","options":["Danh sách rỗng","Chỉ dữ liệu trung bình","Chỉ dữ liệu lớn ngẫu nhiên","Chỉ đầu ra đúng mẫu"]},{"text":"Vì sao cần tách cấu trúc dữ liệu và giải thuật?","options":["Dễ chọn cách lưu trữ và xử lý phù hợp","Để cấm kiểm thử","Để bỏ qua bộ nhớ","Để tránh mô tả bài toán"]}]},{"order":2,"title":"Phân tích độ phức tạp","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 02 — Phân tích độ phức tạp\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Đo độ phức tạp\nCài đặt hai cách tính tổng từ 1 đến n: duyệt vòng lặp và công thức n(n+1)/2. Đếm số phép cộng theo n và so sánh xu hướng khi n tăng.\n\nCA KIỂM THỬ BẮT BUỘC\nThử n=0, 1, 10, 100, 10000; phân biệt thời gian chạy đo được và độ phức tạp tiệm cận.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Độ phức tạp O(1) biểu thị gì?","options":["Số thao tác tăng không phụ thuộc n theo mô hình xét","Luôn đúng một nanogiây","Luôn dùng một byte","Không có phép tính"]},{"text":"Duyệt tuần tự n phần tử có độ phức tạp thời gian nào?","options":["O(n)","O(1)","O(log n)","O(n² log n)"]},{"text":"Hai vòng lặp lồng nhau, mỗi vòng n lần có độ phức tạp thường là?","options":["O(n²)","O(n)","O(log n)","O(1)"]},{"text":"Tìm kiếm nhị phân trên dãy đã sắp xếp có độ phức tạp xấu nhất?","options":["O(log n)","O(n²)","O(n)","O(1) với mọi kích thước"]},{"text":"Ký hiệu Big-O mô tả điều gì?","options":["Cận trên tăng trưởng tiệm cận","Thời gian đo tuyệt đối","Số lỗi biên dịch","Dung lượng đĩa cố định"]},{"text":"Khi n đủ lớn, n² tăng so với n như thế nào?","options":["Nhanh hơn theo bậc tăng trưởng","Chậm hơn","Luôn bằng","Không thể so sánh"]},{"text":"Đoạn for i từ 1 đến n chỉ cộng biến đếm có độ phức tạp?","options":["O(n)","O(n²)","O(log n)","O(2^n)"]},{"text":"Thuật toán chia đôi liên tiếp kích thước bài toán thường có số bước?","options":["O(log n)","O(n²)","O(n!)","O(n³)"]},{"text":"O(n + n²) được rút gọn thành gì?","options":["O(n²)","O(n)","O(1)","O(log n)"]},{"text":"Phân tích độ phức tạp bộ nhớ đo gì?","options":["Lượng bộ nhớ phụ tăng theo kích thước đầu vào","Số lần bấm chuột","Chỉ thời gian CPU","Kích thước cửa sổ"]}]},{"order":3,"title":"Đệ quy","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 03 — Đệ quy\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Đệ quy tính giai thừa và Fibonacci\nViết hàm giai_thua(n) bằng đệ quy có điều kiện dừng; cài thêm Fibonacci đệ quy và bản lặp, đối chiếu kết quả.\n\nCA KIỂM THỬ BẮT BUỘC\nThử n=0, 1, 5, 10; từ chối n âm; giải thích vì sao Fibonacci đệ quy thuần chậm.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Điều kiện dừng trong đệ quy có vai trò gì?","options":["Ngăn việc gọi hàm vô hạn","Bắt buộc hàm chạy n lần","Xóa toàn bộ ngăn xếp","Thay thế tham số"]},{"text":"Giai thừa 0! bằng bao nhiêu?","options":["1","0","-1","Không xác định"]},{"text":"Giai thừa 5! bằng bao nhiêu?","options":["120","25","15","60"]},{"text":"Công thức đệ quy đúng của n! khi n>0 là gì?","options":["n * (n-1)!","n + (n-1)!","n * n!","(n-1)! / n"]},{"text":"Mỗi lời gọi đệ quy thường được lưu ở đâu?","options":["Call stack","Hàng đợi mạng","Ổ đĩa ngoại vi bắt buộc","CSS"]},{"text":"Đệ quy trực tiếp là khi nào?","options":["Hàm tự gọi chính nó","Hai hàm không liên quan","Chỉ có vòng for","Hàm không có return"]},{"text":"Nếu thiếu điều kiện dừng thích hợp, điều gì có thể xảy ra?","options":["Tràn ngăn xếp lời gọi","Tự sắp xếp kết quả","Luôn trả về 0","Tự xóa dữ liệu"]},{"text":"Fibonacci chuẩn với F(0)=0,F(1)=1 thì F(5) bằng?","options":["5","8","3","10"]},{"text":"Đệ quy thuần tính Fibonacci lớn có nhược điểm gì?","options":["Tính lặp lại nhiều bài toán con","Không thể trả về số","Không dùng điều kiện dừng","Chỉ hoạt động với số âm"]},{"text":"Cách giảm tính toán lặp lại trong Fibonacci đệ quy là gì?","options":["Ghi nhớ kết quả đã tính (memoization)","Tăng số lần gọi lại","Bỏ điều kiện dừng","Thay toàn bộ số bằng chuỗi"]}]},{"order":4,"title":"Mảng và danh sách tuyến tính","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 04 — Mảng và danh sách tuyến tính\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Quản lý mảng số nguyên\nCài đặt chèn, xóa và tìm một phần tử trong mảng/danh sách. Với mỗi thao tác, phân tích số phần tử phải dịch chuyển.\n\nCA KIỂM THỬ BẮT BUỘC\nThử mảng rỗng, một phần tử, chèn đầu/cuối, xóa phần tử không tồn tại và số trùng.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Chỉ số phần tử đầu tiên trong mảng zero-based là?","options":["0","1","-1 luôn hợp lệ","n"]},{"text":"Mảng 6 phần tử zero-based có chỉ số cuối là?","options":["5","6","4","7"]},{"text":"Truy cập mảng qua chỉ số hợp lệ thường có độ phức tạp?","options":["O(1)","O(n)","O(n²)","O(log n)"]},{"text":"Chèn phần tử đầu mảng có n phần tử thường cần gì?","options":["Dịch nhiều phần tử sang phải","Chỉ đổi con trỏ head","Không thay đổi vị trí nào","Tìm đường đi ngắn nhất"]},{"text":"Xóa phần tử ở đầu mảng đặc có thể cần gì?","options":["Dịch phần tử còn lại về trái","Tạo cây mới","Duyệt theo preorder","Đẩy stack"]},{"text":"Tìm tuyến tính trong mảng chưa sắp xếp có độ phức tạp xấu nhất?","options":["O(n)","O(1)","O(log n)","O(n³)"]},{"text":"Đặc điểm nào đúng của mảng?","options":["Các phần tử được đánh địa chỉ qua chỉ số","Chỉ lưu được số nguyên","Không thể truy cập phần tử cuối","Luôn có kích thước bằng một"]},{"text":"Phần tử A[2] của [4,7,9,12] là?","options":["9","7","4","12"]},{"text":"Phép kiểm tra nào quan trọng trước khi truy cập A[i]?","options":["i nằm trong phạm vi chỉ số hợp lệ","i luôn lớn hơn n","A chỉ có một phần tử","i là số thực"]},{"text":"Khi dùng mảng động, thao tác append thường có chi phí bình quân?","options":["O(1) amortized","O(n²) mọi lần","O(log n) mọi lần","O(n!)"]}]},{"order":5,"title":"Danh sách liên kết","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 05 — Danh sách liên kết\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Danh sách liên kết đơn\nTự định nghĩa Node và danh sách liên kết đơn. Cài thêm đầu, thêm cuối, xóa theo giá trị, duyệt và đếm nút. Không dùng danh sách có sẵn để thay việc liên kết nút.\n\nCA KIỂM THỬ BẮT BUỘC\nThử danh sách rỗng, một nút, xóa đầu/cuối, xóa giá trị vắng mặt, chèn cùng giá trị nhiều lần.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Mỗi nút danh sách liên kết đơn thường gồm?","options":["Dữ liệu và liên kết đến nút tiếp theo","Chỉ một chỉ số cố định","Luôn hai con trái phải","Một ma trận kề"]},{"text":"Con trỏ next của nút cuối thường bằng gì?","options":["null / None","head luôn","Nút đầu luôn","Một địa chỉ ngẫu nhiên"]},{"text":"Thêm nút vào đầu danh sách liên kết đơn khi có head thường tốn?","options":["O(1)","O(n)","O(n²)","O(log n)"]},{"text":"Truy cập nút thứ k trong danh sách liên kết đơn thường cần?","options":["Duyệt từ đầu","Truy cập trực tiếp O(1)","Sắp xếp lại toàn bộ","Dùng heap"]},{"text":"Ưu điểm của danh sách liên kết so với mảng khi chèn đầu?","options":["Không cần dịch hàng loạt phần tử","Tìm kiếm luôn O(1)","Truy cập chỉ số luôn O(1)","Không cần bộ nhớ cho liên kết"]},{"text":"Xóa nút đầu trong danh sách không rỗng làm gì?","options":["Đưa head sang head.next","Đổi nút cuối thành head","Tạo mảng mới bắt buộc","Đảo toàn bộ nút"]},{"text":"Danh sách liên kết đơn rỗng có head thường là gì?","options":["null / None","Số 1","Một nút chứa 0 bắt buộc","Nút tail"]},{"text":"Để xóa nút giữa khi chỉ có head, thường cần nhớ gì?","options":["Nút đứng trước nút cần xóa","Chỉ độ cao cây","Chỉ trọng số cạnh","Chỉ màu nút"]},{"text":"Danh sách liên kết đôi có điểm khác gì?","options":["Nút có liên kết trước và sau","Không lưu dữ liệu","Không thể xóa nút","Bắt buộc có vòng"]},{"text":"Duyệt hết danh sách liên kết đơn n nút tốn thời gian?","options":["O(n)","O(1)","O(log n)","O(n²) luôn"]}]},{"order":6,"title":"Ngăn xếp (Stack)","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 06 — Ngăn xếp (Stack)\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Kiểm tra ngoặc cân bằng bằng Stack\nCài stack với push/pop/peek; dùng stack kiểm tra biểu thức chứa (), [] và {} có được đóng đúng thứ tự.\n\nCA KIỂM THỬ BẮT BUỘC\nThử chuỗi rỗng, (), ([{}]), ([)], dấu đóng xuất hiện trước và chuỗi nhiều lớp.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Stack tuân theo nguyên tắc nào?","options":["LIFO","FIFO","FCFS luôn theo thời gian","Random"]},{"text":"Thao tác thêm vào stack gọi là?","options":["push","enqueue","dequeue","sort"]},{"text":"Thao tác lấy phần tử đỉnh stack gọi là?","options":["pop","insertFront","dequeue","merge"]},{"text":"peek/top thường làm gì?","options":["Xem đỉnh mà không loại bỏ","Xóa toàn bộ stack","Thêm vào đáy","Đảo stack"]},{"text":"Push A, push B, pop trả về?","options":["B","A","AB","Không có dữ liệu"]},{"text":"Ứng dụng điển hình của stack là?","options":["Kiểm tra dấu ngoặc cân bằng","Phục vụ khách theo thứ tự đến","Chỉ tìm kiếm nhị phân","Lưu ma trận kề"]},{"text":"Pop trên stack rỗng được gọi là?","options":["Underflow","Overflow của mảng đầy","Tree rotation","Heapify"]},{"text":"Cài stack qua mảng động, push/pop cuối thường có độ phức tạp bình quân?","options":["O(1)","O(n²)","O(log n)","O(n!)"]},{"text":"Với chuỗi \"([{}])\", kiểm tra stack cho kết quả?","options":["Cân bằng","Thiếu dấu đóng","Sai thứ tự đóng","Lỗi kiểu dữ liệu"]},{"text":"Với chuỗi \"([)]\", kiểm tra stack cho kết quả?","options":["Không cân bằng","Cân bằng","Đúng nếu đảo ký tự","Luôn rỗng"]}]},{"order":7,"title":"Hàng đợi (Queue)","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 07 — Hàng đợi (Queue)\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Mô phỏng hàng đợi phục vụ\nCài queue với enqueue/dequeue/front; mô phỏng thứ tự phục vụ 5 khách. Nếu dùng mảng, giải thích chi phí dequeue đầu mảng hoặc dùng chỉ số vòng.\n\nCA KIỂM THỬ BẮT BUỘC\nThử queue rỗng, một khách, dequeue khi rỗng, thêm xen kẽ lấy và phần tử trùng mã.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Queue tuân theo nguyên tắc nào?","options":["FIFO","LIFO","Chỉ dùng đệ quy","Chỉ chứa số"]},{"text":"Thao tác thêm cuối queue gọi là?","options":["enqueue","push vào đầu stack","pop","sort"]},{"text":"Thao tác lấy phần tử đầu queue gọi là?","options":["dequeue","push","peek cuối không xóa","heapify"]},{"text":"Enqueue A, enqueue B, dequeue trả về gì?","options":["A","B","AB","Không có phần tử"]},{"text":"Hàng đợi thường được dùng cho?","options":["Xử lý yêu cầu theo thứ tự đến","Kiểm tra ngoặc với LIFO","Đảo chuỗi bằng pop","Sắp xếp theo BST bắt buộc"]},{"text":"Queue rỗng mà dequeue thì tình huống gì?","options":["Underflow / không có phần tử","Tự sinh phần tử","Trả về phần tử cuối không tồn tại","Luôn trả về 1"]},{"text":"Circular queue dùng kỹ thuật gì?","options":["Quay vòng chỉ số đầu/cuối trong bộ đệm","Luôn cấp phát vô hạn","Sắp xếp lại mọi lần","Đệ quy bắt buộc"]},{"text":"Giữ front và rear cho phép làm gì?","options":["Quản lý hai đầu queue","Xóa mọi phần tử đồng thời","Giảm mọi phép tìm xuống O(1)","Không cần bộ nhớ"]},{"text":"Dequeue đúng từ queue [1,2,3] tạo queue nào?","options":["[2,3]","[1,2]","[3,2]","[1,2,3]"]},{"text":"Cài queue bằng linked list có cả head và tail, enqueue cuối thường là?","options":["O(1)","O(n²)","O(log n)","O(n!)"]}]},{"order":8,"title":"Cây nhị phân","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 08 — Cây nhị phân\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Duyệt cây nhị phân\nTạo cây nhị phân có tối thiểu 7 nút và cài duyệt preorder, inorder, postorder. Với cây tìm kiếm nhị phân, giải thích kết quả inorder.\n\nCA KIỂM THỬ BẮT BUỘC\nThử cây rỗng, chỉ nút gốc, cây lệch trái, cây lệch phải, cây đủ và giá trị trùng.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Mỗi nút cây nhị phân có tối đa bao nhiêu nút con?","options":["2","1","3","Không giới hạn"]},{"text":"Nút không có con được gọi là?","options":["Nút lá","Nút gốc duy nhất","Nút cha của gốc","Cạnh"]},{"text":"Nút cao nhất của cây là?","options":["Nút gốc (root)","Nút lá cuối","Nút trái nhất luôn","Nút phải nhất luôn"]},{"text":"Duyệt inorder theo thứ tự nào?","options":["Trái - Gốc - Phải","Gốc - Trái - Phải","Trái - Phải - Gốc","Phải - Gốc - Trái"]},{"text":"Duyệt preorder theo thứ tự nào?","options":["Gốc - Trái - Phải","Trái - Gốc - Phải","Trái - Phải - Gốc","Phải - Trái - Gốc"]},{"text":"Duyệt postorder theo thứ tự nào?","options":["Trái - Phải - Gốc","Gốc - Trái - Phải","Trái - Gốc - Phải","Gốc - Phải - Trái"]},{"text":"Với cây BST khóa duy nhất, inorder thường cho dãy gì?","options":["Tăng dần","Giảm dần","Ngẫu nhiên","Theo mức"]},{"text":"BST chuẩn đặt các khóa nhỏ hơn nút tại đâu?","options":["Cây con trái","Cây con phải","Luôn ở gốc","Không có quy tắc"]},{"text":"Cây chỉ có một nút có bao nhiêu nút lá?","options":["1","0","2","3"]},{"text":"Duyệt n nút của cây nhị phân tốn thời gian?","options":["O(n)","O(1)","O(log n) với mọi cây","O(n²) bắt buộc"]}]},{"order":9,"title":"Tìm kiếm","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 09 — Tìm kiếm\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Tìm kiếm tuyến tính và nhị phân\nCài tìm kiếm tuyến tính và tìm kiếm nhị phân trên mảng tăng dần. Đếm số lần so sánh để so sánh hai cách tìm.\n\nCA KIỂM THỬ BẮT BUỘC\nThử mảng rỗng, một phần tử, tìm đầu/giữa/cuối, không tồn tại, phần tử trùng; không áp dụng tìm nhị phân cho mảng chưa sắp xếp.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Tìm kiếm nhị phân yêu cầu điều kiện quan trọng nào?","options":["Dãy đã được sắp xếp theo thứ tự xác định","Dãy bắt buộc dài chẵn","Mọi phần tử phải giống nhau","Dãy là danh sách liên kết đôi"]},{"text":"Tìm kiếm tuyến tính trường hợp xấu nhất tốn?","options":["O(n)","O(1)","O(log n)","O(n²)"]},{"text":"Tìm kiếm nhị phân trường hợp xấu nhất tốn?","options":["O(log n)","O(n)","O(n²)","O(2^n)"]},{"text":"Tìm kiếm tuyến tính có áp dụng cho mảng chưa sắp xếp không?","options":["Có","Không","Chỉ mảng chẵn","Chỉ mảng dài 1"]},{"text":"Khi phần tử giữa nhỏ hơn giá trị cần tìm trong mảng tăng dần, tiếp theo tìm ở đâu?","options":["Nửa bên phải","Nửa bên trái","Dừng ngay vì không thấy","Toàn bộ từ đầu"]},{"text":"Khi phần tử giữa lớn hơn giá trị cần tìm trong mảng tăng dần, tiếp theo tìm ở đâu?","options":["Nửa bên trái","Nửa bên phải","Dừng ngay vì không thấy","Toàn bộ từ đầu"]},{"text":"Tìm kiếm nhị phân giảm miền tìm kiếm như thế nào?","options":["Loại khoảng một nửa mỗi bước","Giảm đúng một phần tử mỗi bước","Tăng gấp đôi số phần tử","Không thay đổi"]},{"text":"Nếu mảng rỗng, kết quả tìm một giá trị thường là?","options":["Không tìm thấy","Chỉ số 0","Chỉ số 1","Phần tử null tồn tại"]},{"text":"Binary search với phần tử trùng, bản cài đặt cơ bản bảo đảm gì?","options":["Có thể trả một vị trí khớp, không nhất thiết đầu tiên","Luôn trả vị trí đầu tiên","Luôn trả vị trí cuối cùng","Luôn báo lỗi"]},{"text":"Trong mảng [2,4,6,8,10], phần tử giữa ban đầu là?","options":["6","2","10","8"]}]},{"order":10,"title":"Sắp xếp","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 10 — Sắp xếp\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — So sánh ba thuật toán sắp xếp\nCài bubble sort, selection sort và insertion sort; chạy cùng 5 bộ dữ liệu, đếm số phép so sánh và đổi chỗ.\n\nCA KIỂM THỬ BẮT BUỘC\nThử mảng rỗng, một phần tử, đã tăng, giảm, nhiều giá trị trùng; giải thích độ phức tạp trường hợp xấu nhất.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Bubble sort so sánh chủ yếu những phần tử nào?","options":["Hai phần tử kề nhau","Phần tử đầu và cuối duy nhất","Hai cây con","Chỉ phần tử lớn nhất"]},{"text":"Selection sort mỗi lượt thường làm gì?","options":["Chọn phần tử nhỏ nhất trong đoạn chưa sắp xếp","Chia mảng làm đôi đệ quy","Duyệt BST inorder","Dùng hash map"]},{"text":"Insertion sort hoạt động bằng cách nào?","options":["Chèn phần tử mới vào đoạn đã sắp xếp","Đổi chỗ ngẫu nhiên","Luôn dùng heap","Luôn phân hoạch quanh pivot"]},{"text":"Độ phức tạp xấu nhất của bubble sort thông thường là?","options":["O(n²)","O(n)","O(log n)","O(1)"]},{"text":"Độ phức tạp xấu nhất của insertion sort là?","options":["O(n²)","O(n)","O(log n)","O(1)"]},{"text":"Merge sort thường có độ phức tạp thời gian xấu nhất là?","options":["O(n log n)","O(n²)","O(1)","O(2^n)"]},{"text":"Quick sort có trường hợp xấu nhất là?","options":["O(n²)","O(1)","O(log n) luôn","O(n!)"]},{"text":"Sắp xếp ổn định nghĩa là gì?","options":["Giữ thứ tự tương đối của phần tử bằng khóa","Luôn chạy O(1)","Không dùng bộ nhớ","Luôn chạy nhanh nhất"]},{"text":"Insertion sort thường hiệu quả với trường hợp nào?","options":["Dữ liệu ít và gần có thứ tự","Chỉ dữ liệu cực lớn ngẫu nhiên","Dữ liệu không thể so sánh","Chỉ mảng rỗng"]},{"text":"Sắp xếp tăng dần [5,2,4,1] có kết quả nào?","options":["[1,2,4,5]","[5,4,2,1]","[2,1,5,4]","[1,4,2,5]"]}]}]$data$::jsonb)->(rec.rn::integer-1);
  IF item IS NULL OR trim(regexp_replace(rec.title, '^[[:space:]]*[0-9]+[[:space:]]*[.·:-]*[[:space:]]*',''))<>item->>'title'
  THEN RAISE EXCEPTION 'DSA lesson % title mismatch: %',rec.rn,rec.title; END IF;
  IF rec.content IS NOT NULL AND rec.content NOT LIKE 'Đọc giáo trình Đỗ Xuân Lôi%' AND rec.content NOT LIKE '[VEDU-DSA-PRACTICE-V1]%'
  THEN RAISE EXCEPTION 'DSA lesson % has custom content, refusing overwrite',rec.rn; END IF;
  SELECT count(*) INTO v_bad FROM assessment.quizzes q
  WHERE q.course_id=v_course AND q.lesson_id=rec.lesson_id AND q.is_published AND NOT q.is_deleted
    AND coalesce(q.description,'') NOT LIKE '[VEDU-LESSON-QUIZ-V1]%'
    AND coalesce(q.description,'') NOT LIKE '[VEDU-DSA-LESSON-10Q-V1]%';
  IF v_bad>0 THEN RAISE EXCEPTION 'DSA lesson % has teacher quiz; refusing replace',rec.rn; END IF;
  IF (SELECT count(*) FROM assessment.quizzes WHERE course_id=v_course AND lesson_id=rec.lesson_id AND NOT is_deleted
   AND description='[VEDU-DSA-LESSON-10Q-V1] Questions authored by VEDU based on DSA reference')>1
  THEN RAISE EXCEPTION 'Duplicate VEDU DSA quiz lesson %',rec.rn; END IF;
 END LOOP;
 -- Preflight passed. Keep old quiz and attempt history, only unpublish generated old quiz.
 FOR rec IN SELECT l.lesson_id,l.title,row_number() OVER(ORDER BY l.lesson_order,l.lesson_id) rn
 FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
 WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted
 LOOP
  item := ($data$[{"order":1,"title":"Tổng quan cấu trúc dữ liệu và giải thuật","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 01 — Tổng quan cấu trúc dữ liệu và giải thuật\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — So sánh cấu trúc dữ liệu\nViết chương trình lưu 5 sinh viên (mã, tên, điểm) vào danh sách, cho phép tìm theo mã và thống kê điểm trung bình. Vẽ sơ đồ mô tả đầu vào, xử lý, đầu ra.\n\nCA KIỂM THỬ BẮT BUỘC\nDanh sách rỗng; một sinh viên; mã trùng; tìm mã không tồn tại; điểm 0 và 10.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Cấu trúc dữ liệu dùng để làm gì?","options":["Tổ chức và lưu dữ liệu để thao tác hiệu quả","Chỉ tạo giao diện đồ họa","Thay thế hệ điều hành","Chỉ lưu tập tin âm thanh"]},{"text":"Giải thuật là gì?","options":["Dãy bước hữu hạn để giải một bài toán","Một ngôn ngữ lập trình cụ thể","Tên của bộ xử lý","Một kiểu tệp dữ liệu"]},{"text":"Đặc trưng nào thường cần đánh giá khi chọn giải thuật?","options":["Thời gian và bộ nhớ sử dụng","Màu sắc màn hình","Tên tác giả duy nhất","Dung lượng ảnh nền"]},{"text":"Dữ liệu đầu vào của thuật toán tìm lớn nhất là gì?","options":["Một tập giá trị cần so sánh","Mã lệnh giao diện","Tên hệ điều hành","Tệp CSS"]},{"text":"Tính đúng đắn của giải thuật nghĩa là gì?","options":["Cho kết quả đúng theo đặc tả với đầu vào hợp lệ","Luôn chạy nhanh nhất","Không dùng bộ nhớ","Có nhiều dòng code"]},{"text":"Cấu trúc nào hỗ trợ truy cập phần tử qua chỉ số?","options":["Mảng","Danh sách liên kết đơn chỉ có con trỏ đầu","Ngăn xếp chỉ cho pop","Hàng đợi chỉ cho dequeue"]},{"text":"Giải thuật cần điều kiện dừng để làm gì?","options":["Tránh thực hiện vô hạn với đầu vào hợp lệ","Tăng số vòng lặp","Tạo màu cho kết quả","Buộc sử dụng đệ quy"]},{"text":"Tính trừu tượng dữ liệu (ADT) mô tả điều gì?","options":["Các phép toán và hành vi mà không buộc cách cài đặt","Một tệp PDF","Địa chỉ IP của máy","Tốc độ CPU cố định"]},{"text":"Một phép kiểm thử biên cho tập dữ liệu là gì?","options":["Danh sách rỗng","Chỉ dữ liệu trung bình","Chỉ dữ liệu lớn ngẫu nhiên","Chỉ đầu ra đúng mẫu"]},{"text":"Vì sao cần tách cấu trúc dữ liệu và giải thuật?","options":["Dễ chọn cách lưu trữ và xử lý phù hợp","Để cấm kiểm thử","Để bỏ qua bộ nhớ","Để tránh mô tả bài toán"]}]},{"order":2,"title":"Phân tích độ phức tạp","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 02 — Phân tích độ phức tạp\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Đo độ phức tạp\nCài đặt hai cách tính tổng từ 1 đến n: duyệt vòng lặp và công thức n(n+1)/2. Đếm số phép cộng theo n và so sánh xu hướng khi n tăng.\n\nCA KIỂM THỬ BẮT BUỘC\nThử n=0, 1, 10, 100, 10000; phân biệt thời gian chạy đo được và độ phức tạp tiệm cận.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Độ phức tạp O(1) biểu thị gì?","options":["Số thao tác tăng không phụ thuộc n theo mô hình xét","Luôn đúng một nanogiây","Luôn dùng một byte","Không có phép tính"]},{"text":"Duyệt tuần tự n phần tử có độ phức tạp thời gian nào?","options":["O(n)","O(1)","O(log n)","O(n² log n)"]},{"text":"Hai vòng lặp lồng nhau, mỗi vòng n lần có độ phức tạp thường là?","options":["O(n²)","O(n)","O(log n)","O(1)"]},{"text":"Tìm kiếm nhị phân trên dãy đã sắp xếp có độ phức tạp xấu nhất?","options":["O(log n)","O(n²)","O(n)","O(1) với mọi kích thước"]},{"text":"Ký hiệu Big-O mô tả điều gì?","options":["Cận trên tăng trưởng tiệm cận","Thời gian đo tuyệt đối","Số lỗi biên dịch","Dung lượng đĩa cố định"]},{"text":"Khi n đủ lớn, n² tăng so với n như thế nào?","options":["Nhanh hơn theo bậc tăng trưởng","Chậm hơn","Luôn bằng","Không thể so sánh"]},{"text":"Đoạn for i từ 1 đến n chỉ cộng biến đếm có độ phức tạp?","options":["O(n)","O(n²)","O(log n)","O(2^n)"]},{"text":"Thuật toán chia đôi liên tiếp kích thước bài toán thường có số bước?","options":["O(log n)","O(n²)","O(n!)","O(n³)"]},{"text":"O(n + n²) được rút gọn thành gì?","options":["O(n²)","O(n)","O(1)","O(log n)"]},{"text":"Phân tích độ phức tạp bộ nhớ đo gì?","options":["Lượng bộ nhớ phụ tăng theo kích thước đầu vào","Số lần bấm chuột","Chỉ thời gian CPU","Kích thước cửa sổ"]}]},{"order":3,"title":"Đệ quy","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 03 — Đệ quy\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Đệ quy tính giai thừa và Fibonacci\nViết hàm giai_thua(n) bằng đệ quy có điều kiện dừng; cài thêm Fibonacci đệ quy và bản lặp, đối chiếu kết quả.\n\nCA KIỂM THỬ BẮT BUỘC\nThử n=0, 1, 5, 10; từ chối n âm; giải thích vì sao Fibonacci đệ quy thuần chậm.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Điều kiện dừng trong đệ quy có vai trò gì?","options":["Ngăn việc gọi hàm vô hạn","Bắt buộc hàm chạy n lần","Xóa toàn bộ ngăn xếp","Thay thế tham số"]},{"text":"Giai thừa 0! bằng bao nhiêu?","options":["1","0","-1","Không xác định"]},{"text":"Giai thừa 5! bằng bao nhiêu?","options":["120","25","15","60"]},{"text":"Công thức đệ quy đúng của n! khi n>0 là gì?","options":["n * (n-1)!","n + (n-1)!","n * n!","(n-1)! / n"]},{"text":"Mỗi lời gọi đệ quy thường được lưu ở đâu?","options":["Call stack","Hàng đợi mạng","Ổ đĩa ngoại vi bắt buộc","CSS"]},{"text":"Đệ quy trực tiếp là khi nào?","options":["Hàm tự gọi chính nó","Hai hàm không liên quan","Chỉ có vòng for","Hàm không có return"]},{"text":"Nếu thiếu điều kiện dừng thích hợp, điều gì có thể xảy ra?","options":["Tràn ngăn xếp lời gọi","Tự sắp xếp kết quả","Luôn trả về 0","Tự xóa dữ liệu"]},{"text":"Fibonacci chuẩn với F(0)=0,F(1)=1 thì F(5) bằng?","options":["5","8","3","10"]},{"text":"Đệ quy thuần tính Fibonacci lớn có nhược điểm gì?","options":["Tính lặp lại nhiều bài toán con","Không thể trả về số","Không dùng điều kiện dừng","Chỉ hoạt động với số âm"]},{"text":"Cách giảm tính toán lặp lại trong Fibonacci đệ quy là gì?","options":["Ghi nhớ kết quả đã tính (memoization)","Tăng số lần gọi lại","Bỏ điều kiện dừng","Thay toàn bộ số bằng chuỗi"]}]},{"order":4,"title":"Mảng và danh sách tuyến tính","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 04 — Mảng và danh sách tuyến tính\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Quản lý mảng số nguyên\nCài đặt chèn, xóa và tìm một phần tử trong mảng/danh sách. Với mỗi thao tác, phân tích số phần tử phải dịch chuyển.\n\nCA KIỂM THỬ BẮT BUỘC\nThử mảng rỗng, một phần tử, chèn đầu/cuối, xóa phần tử không tồn tại và số trùng.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Chỉ số phần tử đầu tiên trong mảng zero-based là?","options":["0","1","-1 luôn hợp lệ","n"]},{"text":"Mảng 6 phần tử zero-based có chỉ số cuối là?","options":["5","6","4","7"]},{"text":"Truy cập mảng qua chỉ số hợp lệ thường có độ phức tạp?","options":["O(1)","O(n)","O(n²)","O(log n)"]},{"text":"Chèn phần tử đầu mảng có n phần tử thường cần gì?","options":["Dịch nhiều phần tử sang phải","Chỉ đổi con trỏ head","Không thay đổi vị trí nào","Tìm đường đi ngắn nhất"]},{"text":"Xóa phần tử ở đầu mảng đặc có thể cần gì?","options":["Dịch phần tử còn lại về trái","Tạo cây mới","Duyệt theo preorder","Đẩy stack"]},{"text":"Tìm tuyến tính trong mảng chưa sắp xếp có độ phức tạp xấu nhất?","options":["O(n)","O(1)","O(log n)","O(n³)"]},{"text":"Đặc điểm nào đúng của mảng?","options":["Các phần tử được đánh địa chỉ qua chỉ số","Chỉ lưu được số nguyên","Không thể truy cập phần tử cuối","Luôn có kích thước bằng một"]},{"text":"Phần tử A[2] của [4,7,9,12] là?","options":["9","7","4","12"]},{"text":"Phép kiểm tra nào quan trọng trước khi truy cập A[i]?","options":["i nằm trong phạm vi chỉ số hợp lệ","i luôn lớn hơn n","A chỉ có một phần tử","i là số thực"]},{"text":"Khi dùng mảng động, thao tác append thường có chi phí bình quân?","options":["O(1) amortized","O(n²) mọi lần","O(log n) mọi lần","O(n!)"]}]},{"order":5,"title":"Danh sách liên kết","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 05 — Danh sách liên kết\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Danh sách liên kết đơn\nTự định nghĩa Node và danh sách liên kết đơn. Cài thêm đầu, thêm cuối, xóa theo giá trị, duyệt và đếm nút. Không dùng danh sách có sẵn để thay việc liên kết nút.\n\nCA KIỂM THỬ BẮT BUỘC\nThử danh sách rỗng, một nút, xóa đầu/cuối, xóa giá trị vắng mặt, chèn cùng giá trị nhiều lần.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Mỗi nút danh sách liên kết đơn thường gồm?","options":["Dữ liệu và liên kết đến nút tiếp theo","Chỉ một chỉ số cố định","Luôn hai con trái phải","Một ma trận kề"]},{"text":"Con trỏ next của nút cuối thường bằng gì?","options":["null / None","head luôn","Nút đầu luôn","Một địa chỉ ngẫu nhiên"]},{"text":"Thêm nút vào đầu danh sách liên kết đơn khi có head thường tốn?","options":["O(1)","O(n)","O(n²)","O(log n)"]},{"text":"Truy cập nút thứ k trong danh sách liên kết đơn thường cần?","options":["Duyệt từ đầu","Truy cập trực tiếp O(1)","Sắp xếp lại toàn bộ","Dùng heap"]},{"text":"Ưu điểm của danh sách liên kết so với mảng khi chèn đầu?","options":["Không cần dịch hàng loạt phần tử","Tìm kiếm luôn O(1)","Truy cập chỉ số luôn O(1)","Không cần bộ nhớ cho liên kết"]},{"text":"Xóa nút đầu trong danh sách không rỗng làm gì?","options":["Đưa head sang head.next","Đổi nút cuối thành head","Tạo mảng mới bắt buộc","Đảo toàn bộ nút"]},{"text":"Danh sách liên kết đơn rỗng có head thường là gì?","options":["null / None","Số 1","Một nút chứa 0 bắt buộc","Nút tail"]},{"text":"Để xóa nút giữa khi chỉ có head, thường cần nhớ gì?","options":["Nút đứng trước nút cần xóa","Chỉ độ cao cây","Chỉ trọng số cạnh","Chỉ màu nút"]},{"text":"Danh sách liên kết đôi có điểm khác gì?","options":["Nút có liên kết trước và sau","Không lưu dữ liệu","Không thể xóa nút","Bắt buộc có vòng"]},{"text":"Duyệt hết danh sách liên kết đơn n nút tốn thời gian?","options":["O(n)","O(1)","O(log n)","O(n²) luôn"]}]},{"order":6,"title":"Ngăn xếp (Stack)","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 06 — Ngăn xếp (Stack)\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Kiểm tra ngoặc cân bằng bằng Stack\nCài stack với push/pop/peek; dùng stack kiểm tra biểu thức chứa (), [] và {} có được đóng đúng thứ tự.\n\nCA KIỂM THỬ BẮT BUỘC\nThử chuỗi rỗng, (), ([{}]), ([)], dấu đóng xuất hiện trước và chuỗi nhiều lớp.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Stack tuân theo nguyên tắc nào?","options":["LIFO","FIFO","FCFS luôn theo thời gian","Random"]},{"text":"Thao tác thêm vào stack gọi là?","options":["push","enqueue","dequeue","sort"]},{"text":"Thao tác lấy phần tử đỉnh stack gọi là?","options":["pop","insertFront","dequeue","merge"]},{"text":"peek/top thường làm gì?","options":["Xem đỉnh mà không loại bỏ","Xóa toàn bộ stack","Thêm vào đáy","Đảo stack"]},{"text":"Push A, push B, pop trả về?","options":["B","A","AB","Không có dữ liệu"]},{"text":"Ứng dụng điển hình của stack là?","options":["Kiểm tra dấu ngoặc cân bằng","Phục vụ khách theo thứ tự đến","Chỉ tìm kiếm nhị phân","Lưu ma trận kề"]},{"text":"Pop trên stack rỗng được gọi là?","options":["Underflow","Overflow của mảng đầy","Tree rotation","Heapify"]},{"text":"Cài stack qua mảng động, push/pop cuối thường có độ phức tạp bình quân?","options":["O(1)","O(n²)","O(log n)","O(n!)"]},{"text":"Với chuỗi \"([{}])\", kiểm tra stack cho kết quả?","options":["Cân bằng","Thiếu dấu đóng","Sai thứ tự đóng","Lỗi kiểu dữ liệu"]},{"text":"Với chuỗi \"([)]\", kiểm tra stack cho kết quả?","options":["Không cân bằng","Cân bằng","Đúng nếu đảo ký tự","Luôn rỗng"]}]},{"order":7,"title":"Hàng đợi (Queue)","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 07 — Hàng đợi (Queue)\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Mô phỏng hàng đợi phục vụ\nCài queue với enqueue/dequeue/front; mô phỏng thứ tự phục vụ 5 khách. Nếu dùng mảng, giải thích chi phí dequeue đầu mảng hoặc dùng chỉ số vòng.\n\nCA KIỂM THỬ BẮT BUỘC\nThử queue rỗng, một khách, dequeue khi rỗng, thêm xen kẽ lấy và phần tử trùng mã.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Queue tuân theo nguyên tắc nào?","options":["FIFO","LIFO","Chỉ dùng đệ quy","Chỉ chứa số"]},{"text":"Thao tác thêm cuối queue gọi là?","options":["enqueue","push vào đầu stack","pop","sort"]},{"text":"Thao tác lấy phần tử đầu queue gọi là?","options":["dequeue","push","peek cuối không xóa","heapify"]},{"text":"Enqueue A, enqueue B, dequeue trả về gì?","options":["A","B","AB","Không có phần tử"]},{"text":"Hàng đợi thường được dùng cho?","options":["Xử lý yêu cầu theo thứ tự đến","Kiểm tra ngoặc với LIFO","Đảo chuỗi bằng pop","Sắp xếp theo BST bắt buộc"]},{"text":"Queue rỗng mà dequeue thì tình huống gì?","options":["Underflow / không có phần tử","Tự sinh phần tử","Trả về phần tử cuối không tồn tại","Luôn trả về 1"]},{"text":"Circular queue dùng kỹ thuật gì?","options":["Quay vòng chỉ số đầu/cuối trong bộ đệm","Luôn cấp phát vô hạn","Sắp xếp lại mọi lần","Đệ quy bắt buộc"]},{"text":"Giữ front và rear cho phép làm gì?","options":["Quản lý hai đầu queue","Xóa mọi phần tử đồng thời","Giảm mọi phép tìm xuống O(1)","Không cần bộ nhớ"]},{"text":"Dequeue đúng từ queue [1,2,3] tạo queue nào?","options":["[2,3]","[1,2]","[3,2]","[1,2,3]"]},{"text":"Cài queue bằng linked list có cả head và tail, enqueue cuối thường là?","options":["O(1)","O(n²)","O(log n)","O(n!)"]}]},{"order":8,"title":"Cây nhị phân","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 08 — Cây nhị phân\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Duyệt cây nhị phân\nTạo cây nhị phân có tối thiểu 7 nút và cài duyệt preorder, inorder, postorder. Với cây tìm kiếm nhị phân, giải thích kết quả inorder.\n\nCA KIỂM THỬ BẮT BUỘC\nThử cây rỗng, chỉ nút gốc, cây lệch trái, cây lệch phải, cây đủ và giá trị trùng.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Mỗi nút cây nhị phân có tối đa bao nhiêu nút con?","options":["2","1","3","Không giới hạn"]},{"text":"Nút không có con được gọi là?","options":["Nút lá","Nút gốc duy nhất","Nút cha của gốc","Cạnh"]},{"text":"Nút cao nhất của cây là?","options":["Nút gốc (root)","Nút lá cuối","Nút trái nhất luôn","Nút phải nhất luôn"]},{"text":"Duyệt inorder theo thứ tự nào?","options":["Trái - Gốc - Phải","Gốc - Trái - Phải","Trái - Phải - Gốc","Phải - Gốc - Trái"]},{"text":"Duyệt preorder theo thứ tự nào?","options":["Gốc - Trái - Phải","Trái - Gốc - Phải","Trái - Phải - Gốc","Phải - Trái - Gốc"]},{"text":"Duyệt postorder theo thứ tự nào?","options":["Trái - Phải - Gốc","Gốc - Trái - Phải","Trái - Gốc - Phải","Gốc - Phải - Trái"]},{"text":"Với cây BST khóa duy nhất, inorder thường cho dãy gì?","options":["Tăng dần","Giảm dần","Ngẫu nhiên","Theo mức"]},{"text":"BST chuẩn đặt các khóa nhỏ hơn nút tại đâu?","options":["Cây con trái","Cây con phải","Luôn ở gốc","Không có quy tắc"]},{"text":"Cây chỉ có một nút có bao nhiêu nút lá?","options":["1","0","2","3"]},{"text":"Duyệt n nút của cây nhị phân tốn thời gian?","options":["O(n)","O(1)","O(log n) với mọi cây","O(n²) bắt buộc"]}]},{"order":9,"title":"Tìm kiếm","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 09 — Tìm kiếm\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — Tìm kiếm tuyến tính và nhị phân\nCài tìm kiếm tuyến tính và tìm kiếm nhị phân trên mảng tăng dần. Đếm số lần so sánh để so sánh hai cách tìm.\n\nCA KIỂM THỬ BẮT BUỘC\nThử mảng rỗng, một phần tử, tìm đầu/giữa/cuối, không tồn tại, phần tử trùng; không áp dụng tìm nhị phân cho mảng chưa sắp xếp.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Tìm kiếm nhị phân yêu cầu điều kiện quan trọng nào?","options":["Dãy đã được sắp xếp theo thứ tự xác định","Dãy bắt buộc dài chẵn","Mọi phần tử phải giống nhau","Dãy là danh sách liên kết đôi"]},{"text":"Tìm kiếm tuyến tính trường hợp xấu nhất tốn?","options":["O(n)","O(1)","O(log n)","O(n²)"]},{"text":"Tìm kiếm nhị phân trường hợp xấu nhất tốn?","options":["O(log n)","O(n)","O(n²)","O(2^n)"]},{"text":"Tìm kiếm tuyến tính có áp dụng cho mảng chưa sắp xếp không?","options":["Có","Không","Chỉ mảng chẵn","Chỉ mảng dài 1"]},{"text":"Khi phần tử giữa nhỏ hơn giá trị cần tìm trong mảng tăng dần, tiếp theo tìm ở đâu?","options":["Nửa bên phải","Nửa bên trái","Dừng ngay vì không thấy","Toàn bộ từ đầu"]},{"text":"Khi phần tử giữa lớn hơn giá trị cần tìm trong mảng tăng dần, tiếp theo tìm ở đâu?","options":["Nửa bên trái","Nửa bên phải","Dừng ngay vì không thấy","Toàn bộ từ đầu"]},{"text":"Tìm kiếm nhị phân giảm miền tìm kiếm như thế nào?","options":["Loại khoảng một nửa mỗi bước","Giảm đúng một phần tử mỗi bước","Tăng gấp đôi số phần tử","Không thay đổi"]},{"text":"Nếu mảng rỗng, kết quả tìm một giá trị thường là?","options":["Không tìm thấy","Chỉ số 0","Chỉ số 1","Phần tử null tồn tại"]},{"text":"Binary search với phần tử trùng, bản cài đặt cơ bản bảo đảm gì?","options":["Có thể trả một vị trí khớp, không nhất thiết đầu tiên","Luôn trả vị trí đầu tiên","Luôn trả vị trí cuối cùng","Luôn báo lỗi"]},{"text":"Trong mảng [2,4,6,8,10], phần tử giữa ban đầu là?","options":["6","2","10","8"]}]},{"order":10,"title":"Sắp xếp","content":"[VEDU-DSA-PRACTICE-V1]\nMỤC TIÊU BÀI 10 — Sắp xếp\nNắm vững khái niệm, cài đặt giải thuật và tự đánh giá độ phức tạp.\n\nBÀI THỰC HÀNH TỰ NGUYỆN — So sánh ba thuật toán sắp xếp\nCài bubble sort, selection sort và insertion sort; chạy cùng 5 bộ dữ liệu, đếm số phép so sánh và đổi chỗ.\n\nCA KIỂM THỬ BẮT BUỘC\nThử mảng rỗng, một phần tử, đã tăng, giảm, nhiều giá trị trùng; giải thích độ phức tạp trường hợp xấu nhất.\n\nTIÊU CHÍ GỢI Ý (10 ĐIỂM)\nChạy đúng và đầy đủ: 4 điểm; xử lý biên: 2; kiểm thử và bằng chứng: 2; giải thích độ phức tạp/nguồn: 2.\n\nBài thực hành chỉ để luyện tập, không chặn mở bài tiếp theo. Học viên cần đạt quiz bài hiện tại theo quy định.\n\nNguồn kiến thức tham khảo (không phải nguồn đề bài): https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/\nĐề thực hành do VEDU biên soạn.","questions":[{"text":"Bubble sort so sánh chủ yếu những phần tử nào?","options":["Hai phần tử kề nhau","Phần tử đầu và cuối duy nhất","Hai cây con","Chỉ phần tử lớn nhất"]},{"text":"Selection sort mỗi lượt thường làm gì?","options":["Chọn phần tử nhỏ nhất trong đoạn chưa sắp xếp","Chia mảng làm đôi đệ quy","Duyệt BST inorder","Dùng hash map"]},{"text":"Insertion sort hoạt động bằng cách nào?","options":["Chèn phần tử mới vào đoạn đã sắp xếp","Đổi chỗ ngẫu nhiên","Luôn dùng heap","Luôn phân hoạch quanh pivot"]},{"text":"Độ phức tạp xấu nhất của bubble sort thông thường là?","options":["O(n²)","O(n)","O(log n)","O(1)"]},{"text":"Độ phức tạp xấu nhất của insertion sort là?","options":["O(n²)","O(n)","O(log n)","O(1)"]},{"text":"Merge sort thường có độ phức tạp thời gian xấu nhất là?","options":["O(n log n)","O(n²)","O(1)","O(2^n)"]},{"text":"Quick sort có trường hợp xấu nhất là?","options":["O(n²)","O(1)","O(log n) luôn","O(n!)"]},{"text":"Sắp xếp ổn định nghĩa là gì?","options":["Giữ thứ tự tương đối của phần tử bằng khóa","Luôn chạy O(1)","Không dùng bộ nhớ","Luôn chạy nhanh nhất"]},{"text":"Insertion sort thường hiệu quả với trường hợp nào?","options":["Dữ liệu ít và gần có thứ tự","Chỉ dữ liệu cực lớn ngẫu nhiên","Dữ liệu không thể so sánh","Chỉ mảng rỗng"]},{"text":"Sắp xếp tăng dần [5,2,4,1] có kết quả nào?","options":["[1,2,4,5]","[5,4,2,1]","[2,1,5,4]","[1,4,2,5]"]}]}]$data$::jsonb)->(rec.rn::integer-1);
  UPDATE lms.lessons SET content=item->>'content', updated_at=now()
    WHERE lesson_id=rec.lesson_id AND content IS DISTINCT FROM item->>'content';
  SELECT quiz_id INTO v_quiz FROM assessment.quizzes
    WHERE course_id=v_course AND lesson_id=rec.lesson_id AND NOT is_deleted
    AND description='[VEDU-DSA-LESSON-10Q-V1] Questions authored by VEDU based on DSA reference' LIMIT 1;
  IF v_quiz IS NULL THEN
   INSERT INTO assessment.quizzes(course_id,lesson_id,title,description,time_limit_seconds,passing_score,max_attempts,is_published)
   VALUES(v_course,rec.lesson_id,'Quiz cuối bài — '||rec.title,
    '[VEDU-DSA-LESSON-10Q-V1] Questions authored by VEDU based on DSA reference',900,7,3,false)
   RETURNING quiz_id INTO v_quiz;
   v_order:=0;
   FOR question IN SELECT value FROM jsonb_array_elements(item->'questions') LOOP
    v_order:=v_order+1;
    INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
    VALUES(v_quiz,question->>'text','SINGLE_CHOICE',v_order,1) RETURNING question_id INTO v_qid;
    v_answer_order:=0;
    FOR answer IN SELECT value#>>'{}' FROM jsonb_array_elements(question->'options') LOOP
     v_answer_order:=v_answer_order+1;
     INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
       VALUES(v_qid,answer,v_answer_order=1,1+mod(v_answer_order+v_order-2,4));
    END LOOP;
   END LOOP;
  END IF;
  IF (SELECT count(*) FROM assessment.questions WHERE quiz_id=v_quiz)<>10
  THEN RAISE EXCEPTION 'DSA lesson % quiz incomplete',rec.rn; END IF;
  UPDATE assessment.quizzes SET is_published=false,updated_at=now()
   WHERE course_id=v_course AND lesson_id=rec.lesson_id AND NOT is_deleted AND is_published
    AND description LIKE '[VEDU-LESSON-QUIZ-V1]%';
  UPDATE assessment.quizzes SET is_published=true,updated_at=now() WHERE quiz_id=v_quiz AND NOT is_published;
 END LOOP;
END $vedu_dsa_18$;
COMMIT;
